import { Subflow, wfa } from '@servicenow/sdk/automation'
import { BooleanColumn, StringColumn } from '@servicenow/sdk/core'
import { actionInstance } from './pill-examples.now'

export const pill_subflow_2 = Subflow(
    {
        $id: Now.ID['e5079955f75944178c2c271549dd76e2'],
        name: 'pill-subflow-2',
        description: 'a subflow with a pill reference!',
        flowPriority: 'LOW',
        annotation: 'the annotation!',
        inputs: {
            isEmployee: BooleanColumn({
                label: 'input1',
                mandatory: true,
            }),
            empName: StringColumn({
                label: 'a label',
                mandatory: true,
            }),
        },
        outputs: {
            something: BooleanColumn({
                label: 'outputOne',
                mandatory: true,
            }),
            somethingElse: StringColumn({
                label: 'output2',
                mandatory: true,
            }),
        },
        flowVariables: {
            flow_variable1: StringColumn({
                label: 'flow_variable1',
                mandatory: true,
            }),
        },
    },
    (params) => {
        const actionInstance_1 = wfa.action(
            actionInstance,
            {
                $id: Now.ID['f56a03c118f64f7b9c610d4ff472b334'],
            },
            {
                inp1: wfa.dataPill(params.inputs.isEmployee, 'boolean'),
                inp2: wfa.dataPill(params.inputs.empName, 'string'),
                inp3: `Hello ${wfa.dataPill(params.inputs.empName, 'string')}`,
            }
        )
        const actionInstance_2 = wfa.action(
            actionInstance,
            {
                $id: Now.ID['5c88a57b2aab49dea28a91aacbaf6146'],
            },
            {
                inp1: false,
                inp2: wfa.dataPill(params.flowVariables.flow_variable1, 'string'),
                inp3: `Hello ${wfa.dataPill(params.flowVariables.flow_variable1, 'string')}`,
            }
        )
        wfa.action(
            actionInstance,
            {
                $id: Now.ID['b5e4d2eff95c4295ad0c079e3fcd8916'],
            },
            {
                inp1: wfa.dataPill(actionInstance_1.name, 'boolean'),
                inp2: `lead test ${wfa.dataPill(actionInstance_1.name, 'boolean')} something ${wfa.dataPill(actionInstance_2.age, 'string')}`,
                inp3: `Hello ${wfa.dataPill(actionInstance_1.name, 'boolean')}`,
            }
        )
        wfa.subflow(
            '0f41f4e7cdb0449e9a0498cd9d1fd95d',
            {
                $id: Now.ID['78a51a7ee04f42a6aeea5755bd09d511'],
            },
            {
                isEmployee: wfa.dataPill(params.inputs.isEmployee, 'boolean'),
                empName: wfa.dataPill(params.flowVariables.flow_variable1, 'string'),
            }
        )
    }
)
